"""Tokenizer."""

import dataclasses

from .errors import LexError

KEYWORDS = frozenset(
    {"let", "print", "if", "else", "while", "true", "false", "and", "or", "not"}
)
_TWO_CHAR_OPS = ("==", "!=", "<=", ">=")
_ONE_CHAR_OPS = "+-*/%(){};=<>"
_ESCAPES = {"n": "\n", "t": "\t", '"': '"', "\\": "\\"}
_DIGITS = "0123456789"


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str
    text: str
    value: object
    offset: int


def _is_ident_start(ch: str) -> bool:
    return ch == "_" or ("a" <= ch <= "z") or ("A" <= ch <= "Z")


def _digits_end(src: str, pos: int) -> int:
    while pos < len(src) and src[pos] in _DIGITS:
        pos += 1
    return pos


def _lex_number(src: str, start: int) -> tuple[Token, int]:
    pos = _digits_end(src, start)
    if pos < len(src) and src[pos] == ".":
        frac = pos + 1
        end = _digits_end(src, frac)
        if end == frac:
            raise LexError("malformed float", start)
        pos = end
        if pos < len(src) and src[pos] in "eE":
            exp = pos + 1
            if exp < len(src) and src[exp] in "+-":
                exp += 1
            end = _digits_end(src, exp)
            if end == exp:
                raise LexError("malformed exponent", start)
            pos = end
        text = src[start:pos]
        return Token("FLOAT", text, float(text), start), pos
    text = src[start:pos]
    return Token("INT", text, int(text), start), pos


def _lex_string(src: str, start: int) -> tuple[Token, int]:
    pos = start + 1
    out: list[str] = []
    while True:
        if pos >= len(src):
            raise LexError("unterminated string", start)
        ch = src[pos]
        if ch == '"':
            text = "".join(out)
            return Token("STRING", text, text, start), pos + 1
        if ch == "\n":
            raise LexError("newline in string", pos)
        if ch == "\\":
            if pos + 1 >= len(src) or src[pos + 1] not in _ESCAPES:
                raise LexError("invalid escape", pos)
            out.append(_ESCAPES[src[pos + 1]])
            pos += 2
        else:
            out.append(ch)
            pos += 1


def _lex_word(src: str, start: int) -> tuple[Token, int]:
    pos = start + 1
    while pos < len(src) and (_is_ident_start(src[pos]) or src[pos] in _DIGITS):
        pos += 1
    text = src[start:pos]
    kind = "KEYWORD" if text in KEYWORDS else "IDENT"
    return Token(kind, text, text, start), pos


def _skip_trivia(src: str, pos: int) -> int:
    while pos < len(src):
        if src[pos] in " \t\r\n\f\v":
            pos += 1
        elif src.startswith("//", pos):
            while pos < len(src) and src[pos] != "\n":
                pos += 1
        else:
            break
    return pos


def _lex_one(src: str, pos: int) -> tuple[Token, int]:
    ch = src[pos]
    if ch in _DIGITS:
        return _lex_number(src, pos)
    if ch == '"':
        return _lex_string(src, pos)
    if _is_ident_start(ch):
        return _lex_word(src, pos)
    if src[pos:pos + 2] in _TWO_CHAR_OPS:
        return Token("OP", src[pos:pos + 2], src[pos:pos + 2], pos), pos + 2
    if ch in _ONE_CHAR_OPS:
        return Token("OP", ch, ch, pos), pos + 1
    raise LexError(f"unexpected character {ch!r}", pos)


def tokenize(src: str) -> list[Token]:
    tokens: list[Token] = []
    pos = _skip_trivia(src, 0)
    while pos < len(src):
        token, pos = _lex_one(src, pos)
        tokens.append(token)
        pos = _skip_trivia(src, pos)
    return tokens

"""Recursive-descent parser.

AST nodes are tuples whose first element is a tag:
  expressions: ("lit", v) ("var", name) ("un", "-", e) ("not", e)
               ("bin", op, l, r) ("and", l, r) ("or", l, r)
  statements:  ("let", name, e) ("assign", name, e) ("print", e)
               ("if", cond, block, else_block_or_if_or_None)
               ("while", cond, block) ("block", [stmts])
  root:        ("program", [stmts])
"""

from .errors import ParseError
from .lexer import Token, tokenize

_COMPARE = ("==", "!=", "<", "<=", ">", ">=")


class _Parser:
    def __init__(self, src: str) -> None:
        self.src = src
        self.tokens = tokenize(src)
        self.pos = 0

    def peek(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def offset(self) -> int:
        tok = self.peek()
        return tok.offset if tok else len(self.src)

    def is_op(self, text: str) -> bool:
        tok = self.peek()
        return tok is not None and tok.kind == "OP" and tok.text == text

    def is_kw(self, text: str) -> bool:
        tok = self.peek()
        return tok is not None and tok.kind == "KEYWORD" and tok.text == text

    def expect_op(self, text: str) -> None:
        if not self.is_op(text):
            raise ParseError(f"expected {text!r}", self.offset())
        self.pos += 1

    def expect_ident(self) -> str:
        tok = self.peek()
        if tok is None or tok.kind != "IDENT":
            raise ParseError("expected identifier", self.offset())
        self.pos += 1
        return tok.text

    # statements
    def program(self) -> tuple:
        stmts = []
        while self.peek() is not None:
            stmts.append(self.statement())
        return ("program", stmts)

    def block(self) -> tuple:
        self.expect_op("{")
        stmts = []
        while not self.is_op("}"):
            if self.peek() is None:
                raise ParseError("unterminated block", self.offset())
            stmts.append(self.statement())
        self.pos += 1
        return ("block", stmts)

    def statement(self) -> tuple:
        tok = self.peek()
        if tok is None:
            raise ParseError("unexpected end of input", self.offset())
        if tok.kind == "KEYWORD":
            handler = {
                "let": self.let_stmt, "print": self.print_stmt,
                "if": self.if_stmt, "while": self.while_stmt,
            }.get(tok.text)
            if handler is not None:
                self.pos += 1
                return handler()
        elif tok.kind == "IDENT":
            self.pos += 1
            self.expect_op("=")
            value = self.expr()
            self.expect_op(";")
            return ("assign", tok.text, value)
        elif self.is_op("{"):
            return self.block()
        raise ParseError(f"unexpected token {tok.text!r}", tok.offset)

    def let_stmt(self) -> tuple:
        name = self.expect_ident()
        self.expect_op("=")
        value = self.expr()
        self.expect_op(";")
        return ("let", name, value)

    def print_stmt(self) -> tuple:
        value = self.expr()
        self.expect_op(";")
        return ("print", value)

    def paren_cond(self) -> tuple:
        self.expect_op("(")
        cond = self.expr()
        self.expect_op(")")
        return cond

    def if_stmt(self) -> tuple:
        cond = self.paren_cond()
        then = self.block()
        other = None
        if self.is_kw("else"):
            self.pos += 1
            if self.is_kw("if"):
                self.pos += 1
                other = self.if_stmt()
            else:
                other = self.block()
        return ("if", cond, then, other)

    def while_stmt(self) -> tuple:
        cond = self.paren_cond()
        return ("while", cond, self.block())

    # expressions
    def expr(self) -> tuple:
        node = self.and_expr()
        while self.is_kw("or"):
            self.pos += 1
            node = ("or", node, self.and_expr())
        return node

    def and_expr(self) -> tuple:
        node = self.not_expr()
        while self.is_kw("and"):
            self.pos += 1
            node = ("and", node, self.not_expr())
        return node

    def not_expr(self) -> tuple:
        if self.is_kw("not"):
            self.pos += 1
            return ("not", self.not_expr())
        return self.comparison()

    def comparison(self) -> tuple:
        left = self.additive()
        tok = self.peek()
        if tok is not None and tok.kind == "OP" and tok.text in _COMPARE:
            self.pos += 1
            node = ("bin", tok.text, left, self.additive())
            nxt = self.peek()
            if nxt is not None and nxt.kind == "OP" and nxt.text in _COMPARE:
                raise ParseError("comparison is not associative", nxt.offset)
            return node
        return left

    def binary_level(self, ops: tuple, sub) -> tuple:
        node = sub()
        while True:
            tok = self.peek()
            if tok is None or tok.kind != "OP" or tok.text not in ops:
                return node
            self.pos += 1
            node = ("bin", tok.text, node, sub())

    def additive(self) -> tuple:
        return self.binary_level(("+", "-"), self.multiplicative)

    def multiplicative(self) -> tuple:
        return self.binary_level(("*", "/", "%"), self.unary)

    def unary(self) -> tuple:
        if self.is_op("-"):
            self.pos += 1
            return ("un", "-", self.unary())
        return self.primary()

    def primary(self) -> tuple:
        tok = self.peek()
        if tok is None:
            raise ParseError("unexpected end of input", self.offset())
        if tok.kind in ("INT", "FLOAT", "STRING"):
            self.pos += 1
            return ("lit", tok.value)
        if tok.kind == "KEYWORD" and tok.text in ("true", "false"):
            self.pos += 1
            return ("lit", tok.text == "true")
        if tok.kind == "IDENT":
            self.pos += 1
            return ("var", tok.text)
        if self.is_op("("):
            self.pos += 1
            node = self.expr()
            self.expect_op(")")
            return node
        raise ParseError(f"unexpected token {tok.text!r}", tok.offset)


def parse(src: str) -> object:
    try:
        return _Parser(src).program()
    except RecursionError:
        raise ParseError("nesting too deep", 0) from None

