            stmts.append(self.statement())
        return ("program", stmts)

    def block(self) -> tuple:
        self.expect_op("{")
        stmts = []
        while not self.is_op("}"):
            if self.peek() is None:
                raise ParseError("unterminated block", self.offset())
            stmts.append(self.statement())
        self.pos += 1
        return ("block", stmts)

