            handler = {
                "let": self.let_stmt, "print": self.print_stmt,
                "if": self.if_stmt, "while": self.while_stmt,
            }.get(tok.text)
            if handler is not None:
                self.pos += 1
                return handler()
        elif tok.kind == "IDENT":
            self.pos += 1
            self.expect_op("=")
            value = self.expr()
            self.expect_op(";")
            return ("assign", tok.text, value)
        elif self.is_op("{"):
            return self.block()
        raise ParseError(f"unexpected token {tok.text!r}", tok.offset)

