        name = self.expect_ident()
        self.expect_op("=")
        value = self.expr()
        self.expect_op(";")
        return ("let", name, value)

    def print_stmt(self) -> tuple:
        value = self.expr()
        self.expect_op(";")
        return ("print", value)

    def paren_cond(self) -> tuple:
        self.expect_op("(")
        cond = self.expr()
        self.expect_op(")")
        return cond

    def if_stmt(self) -> tuple:
        cond = self.paren_cond()
        then = self.block()
        other = None
        if self.is_kw("else"):
