        return _Parser(src).program()
    except RecursionError:
        raise ParseError("nesting too deep", 0) from None

"""Stack virtual machine and the runtime semantics shared with the optimizer."""

from typing import Callable

from .errors import StepLimitError, VMRuntimeError


def _is_num(v: object) -> bool:
    return type(v) is int or type(v) is float


def _type_name(v: object) -> str:
    return {int: "INT", float: "FLOAT", str: "STRING", bool: "BOOL"}.get(type(v), "?")


def _need_nums(op: str, left: object, right: object) -> None:
    if not (_is_num(left) and _is_num(right)):
        raise VMRuntimeError(
            f"{op}: unsupported operands {_type_name(left)} and {_type_name(right)}"
        )


def _add(left: object, right: object) -> object:
    if type(left) is str and type(right) is str:
        return left + right
    _need_nums("ADD", left, right)
    return left + right  # type: ignore[operator]


def _sub(left: object, right: object) -> object:
    _need_nums("SUB", left, right)
    return left - right  # type: ignore[operator]


def _mul(left: object, right: object) -> object:
    _need_nums("MUL", left, right)
    return left * right  # type: ignore[operator]


def _div(left: object, right: object) -> object:
    _need_nums("DIV", left, right)
    if right == 0:
        raise VMRuntimeError("division by zero")
    return left / right  # type: ignore[operator]


def _mod(left: object, right: object) -> object:
    if type(left) is not int or type(right) is not int:
        raise VMRuntimeError("MOD requires two INT operands")
    if right == 0:
        raise VMRuntimeError("modulo by zero")
    return left % right


def _equal(left: object, right: object) -> bool:
    if _is_num(left) and _is_num(right):
        return left == right
    return type(left) is type(right) and left == right


def _ordered(op: str, left: object, right: object) -> None:
    both_str = type(left) is str and type(right) is str
    if not both_str:
        _need_nums(op, left, right)


def _lt(left: object, right: object) -> object:
    _ordered("LT", left, right)
    return left < right  # type: ignore[operator]


def _le(left: object, right: object) -> object:
    _ordered("LE", left, right)
    return left <= right  # type: ignore[operator]


def _gt(left: object, right: object) -> object:
    _ordered("GT", left, right)
    return left > right  # type: ignore[operator]


def _ge(left: object, right: object) -> object:
    _ordered("GE", left, right)
    return left >= right  # type: ignore[operator]


BINARY_FUNCS: dict[str, Callable[[object, object], object]] = {
    "ADD": _add, "SUB": _sub, "MUL": _mul, "DIV": _div, "MOD": _mod,
    "EQ": lambda a, b: _equal(a, b), "NE": lambda a, b: not _equal(a, b),
    "LT": _lt, "LE": _le, "GT": _gt, "GE": _ge,
}


def apply_binary(op: str, left: object, right: object) -> object:
    try:
        return BINARY_FUNCS[op](left, right)
    except (OverflowError, ValueError) as exc:
        raise VMRuntimeError(f"{op}: numeric error: {exc}") from None


def apply_neg(value: object) -> object:
    if not _is_num(value):
        raise VMRuntimeError(f"NEG: unsupported operand {_type_name(value)}")
    return -value  # type: ignore[operator]


def apply_not(value: object) -> object:
    if type(value) is not bool:
        raise VMRuntimeError(f"NOT: unsupported operand {_type_name(value)}")
    return not value


def render(value: object) -> str:
    if type(value) is bool:
        return "true" if value else "false"
    try:
        return str(value)
    except ValueError as exc:
        raise VMRuntimeError(f"PRINT: cannot render value: {exc}") from None


_UNSET = object()


class _Machine:
    def __init__(self, program: object, step_limit: int) -> None:
        self.program = program
        self.code = program.instructions  # type: ignore[attr-defined]
        self.slots: list = [_UNSET] * len(program.names)  # type: ignore[attr-defined]
        self.stack: list = []
        self.out: list[str] = []
        self.ip = 0
        self.steps = 0
        self.limit = step_limit

    def pop(self) -> object:
        if not self.stack:
            raise VMRuntimeError("stack underflow")
        return self.stack.pop()

    def slot(self, index: object) -> int:
        if type(index) is not int or not 0 <= index < len(self.slots):
            raise VMRuntimeError(f"invalid variable slot {index!r}")
        return index

    def jump(self, target: object) -> None:
        if type(target) is not int or not 0 <= target < len(self.code):
            raise VMRuntimeError(f"invalid jump target {target!r}")
        self.ip = target

    def do_const(self, arg: object) -> None:
        pool = self.program.constants  # type: ignore[attr-defined]
        if type(arg) is not int or not 0 <= arg < len(pool):
            raise VMRuntimeError(f"invalid constant index {arg!r}")
        self.stack.append(pool[arg])

    def do_load(self, arg: object) -> None:
        index = self.slot(arg)
        value = self.slots[index]
        if value is _UNSET:
            name = self.program.names[index]  # type: ignore[attr-defined]
            raise VMRuntimeError(f"variable {name!r} read before assignment")
        self.stack.append(value)

    def do_store(self, arg: object) -> None:
        index = self.slot(arg)
        self.slots[index] = self.pop()

    def do_jif(self, arg: object) -> None:
        cond = self.pop()
        if type(cond) is not bool:
            raise VMRuntimeError(f"condition must be BOOL, got {_type_name(cond)}")
        if not cond:
            self.jump(arg)

    def step(self) -> bool:
        if not 0 <= self.ip < len(self.code):
            raise VMRuntimeError("instruction pointer out of range")
        self.steps += 1
        if self.steps > self.limit:
            raise StepLimitError(f"step limit {self.limit} exceeded")
        instr = self.code[self.ip]
        self.ip += 1
        op, arg = instr.op, instr.arg
        if op in BINARY_FUNCS:
            right = self.pop()
            left = self.pop()
            self.stack.append(apply_binary(op, left, right))
        elif op == "CONST":
            self.do_const(arg)
        elif op == "LOAD":
            self.do_load(arg)
        elif op == "STORE":
            self.do_store(arg)
        elif op == "NEG":
            self.stack.append(apply_neg(self.pop()))
        elif op == "NOT":
            self.stack.append(apply_not(self.pop()))
        elif op == "JUMP":
            self.jump(arg)
        elif op == "JUMP_IF_FALSE":
            self.do_jif(arg)
        elif op == "PRINT":
            self.out.append(render(self.pop()))
        elif op == "POP":
            self.pop()
        elif op == "HALT":
            return False
        else:
            raise VMRuntimeError(f"unknown opcode {op!r}")
        return True


def execute(program: object, *, step_limit: int = 100_000) -> list[str]:
    if type(step_limit) is not int or step_limit <= 0:
        raise ValueError("step_limit must be a positive int")
    machine = _Machine(program, step_limit)
    while machine.step():
        pass
    return machine.out

"""AST constant folding that never changes observable behaviour."""

from .errors import VMRuntimeError
from .opcodes import BINARY_OPCODES
from .vm import apply_binary, apply_neg, apply_not

_INT_MIN = -(2 ** 63)
_INT_MAX = 2 ** 63 - 1


def _is_lit(node: tuple) -> bool:
    return node[0] == "lit"


def _is_bool_lit(node: tuple) -> bool:
    return node[0] == "lit" and type(node[1]) is bool


def _foldable(value: object) -> bool:
    # Huge ints stay unfolded so the constant pool remains serializable.
    return type(value) is not int or _INT_MIN <= value <= _INT_MAX


def _try(func, *args) -> tuple:
    try:
        result = func(*args)
    except VMRuntimeError:
        return ()
    return ("lit", result) if _foldable(result) else ()


def _fold_bin(node: tuple) -> tuple:
    left, right = fold_constants(node[2]), fold_constants(node[3])
    if _is_lit(left) and _is_lit(right):
        folded = _try(apply_binary, BINARY_OPCODES[node[1]], left[1], right[1])
        if folded:
            return folded
    return ("bin", node[1], left, right)


def _fold_un(node: tuple) -> tuple:
    inner = fold_constants(node[2])
    if _is_lit(inner):
        folded = _try(apply_neg, inner[1])
        if folded:
            return folded
    return ("un", "-", inner)


def _fold_not(node: tuple) -> tuple:
    inner = fold_constants(node[1])
    if _is_lit(inner):
        folded = _try(apply_not, inner[1])
        if folded:
            return folded
    return ("not", inner)


def _fold_logic(node: tuple) -> tuple:
    tag = node[0]
    left, right = fold_constants(node[1]), fold_constants(node[2])
    if _is_bool_lit(left):
        # `false and X` / `true or X` never evaluate X.
        if tag == "and" and left[1] is False:
            return ("lit", False)
        if tag == "or" and left[1] is True:
            return ("lit", True)
        if _is_bool_lit(right):
            return ("lit", left[1] and right[1] if tag == "and" else left[1] or right[1])
    return (tag, left, right)


def _fold_block(node: tuple) -> tuple:
    return (node[0], [fold_constants(s) for s in node[1]])


def _fold_opt(node: tuple | None) -> tuple | None:
    return None if node is None else fold_constants(node)


def fold_constants(node: object) -> object:
    tag = node[0]  # type: ignore[index]
    if tag in ("lit", "var"):
        return node
    if tag == "bin":
        return _fold_bin(node)  # type: ignore[arg-type]
    if tag == "un":
        return _fold_un(node)  # type: ignore[arg-type]
    if tag == "not":
        return _fold_not(node)  # type: ignore[arg-type]
    if tag in ("and", "or"):
        return _fold_logic(node)  # type: ignore[arg-type]
    if tag in ("program", "block"):
        return _fold_block(node)  # type: ignore[arg-type]
    if tag in ("let", "assign"):
        return (tag, node[1], fold_constants(node[2]))  # type: ignore[index]
    if tag == "print":
        return (tag, fold_constants(node[1]))  # type: ignore[index]
    if tag == "if":
        return (tag, fold_constants(node[1]), fold_constants(node[2]), _fold_opt(node[3]))  # type: ignore[index]
    if tag == "while":
        return (tag, fold_constants(node[1]), fold_constants(node[2]))  # type: ignore[index]
    raise ValueError(f"unknown AST node {tag!r}")

"""AST -> bytecode compiler."""

import dataclasses

from .errors import CompileError
from .optimizer import fold_constants
from .opcodes import BINARY_OPCODES
from .parser import parse


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str
    arg: int | None


@dataclasses.dataclass
class Program:
    constants: list
    names: list[str]
    instructions: list


def _const_key(value: object) -> tuple:
    # Floats keyed by repr so 0.0 / -0.0 (and NaNs) stay distinct and stable.
    return (type(value), repr(value) if type(value) is float else value)


class _Generator:
    def __init__(self) -> None:
        self.constants: list = []
        self.const_index: dict[tuple, int] = {}
        self.names: list[str] = []
        self.slots: dict[str, int] = {}
        self.code: list[Instr] = []

    def emit(self, op: str, arg: int | None = None) -> int:
        self.code.append(Instr(op, arg))
        return len(self.code) - 1

    def patch(self, at: int, target: int) -> None:
        self.code[at] = Instr(self.code[at].op, target)

    def here(self) -> int:
        return len(self.code)

    def const(self, value: object) -> int:
        key = _const_key(value)
        if key not in self.const_index:
            self.const_index[key] = len(self.constants)
            self.constants.append(value)
        return self.const_index[key]

    def slot_of(self, name: str) -> int:
        if name not in self.slots:
            raise CompileError(f"undeclared variable {name!r}")
        return self.slots[name]

    # statements
    def stmt(self, node: tuple) -> None:
        getattr(self, "s_" + node[0])(node)

    def s_program(self, node: tuple) -> None:
        for child in node[1]:
            self.stmt(child)

    s_block = s_program

    def s_let(self, node: tuple) -> None:
        self.expr(node[2])
        if node[1] in self.slots:
            raise CompileError(f"variable {node[1]!r} already declared")
        self.slots[node[1]] = len(self.names)
        self.names.append(node[1])
        self.emit("STORE", self.slots[node[1]])

    def s_assign(self, node: tuple) -> None:
        slot = self.slot_of(node[1])
        self.expr(node[2])
        self.emit("STORE", slot)

    def s_print(self, node: tuple) -> None:
        self.expr(node[1])
        self.emit("PRINT")

    def s_if(self, node: tuple) -> None:
        self.expr(node[1])
        to_else = self.emit("JUMP_IF_FALSE", 0)
        self.stmt(node[2])
        if node[3] is None:
            self.patch(to_else, self.here())
            return
        to_end = self.emit("JUMP", 0)
        self.patch(to_else, self.here())
        self.stmt(node[3])
        self.patch(to_end, self.here())

    def s_while(self, node: tuple) -> None:
        start = self.here()
        self.expr(node[1])
        to_end = self.emit("JUMP_IF_FALSE", 0)
        self.stmt(node[2])
        self.emit("JUMP", start)
        self.patch(to_end, self.here())

    # expressions
    def expr(self, node: tuple) -> None:
        getattr(self, "e_" + node[0])(node)

    def e_lit(self, node: tuple) -> None:
        self.emit("CONST", self.const(node[1]))

    def e_var(self, node: tuple) -> None:
        self.emit("LOAD", self.slot_of(node[1]))

    def e_un(self, node: tuple) -> None:
        self.expr(node[2])
        self.emit("NEG")

    def e_not(self, node: tuple) -> None:
        self.expr(node[1])
        self.emit("NOT")

    def e_bin(self, node: tuple) -> None:
        self.expr(node[2])
        self.expr(node[3])
        self.emit(BINARY_OPCODES[node[1]])

    def e_and(self, node: tuple) -> None:
        # l; JIF F; r; JIF F; CONST true; JUMP end; F: CONST false; end:
        self.expr(node[1])
        first = self.emit("JUMP_IF_FALSE", 0)
        self.expr(node[2])
        second = self.emit("JUMP_IF_FALSE", 0)
        self.finish_logic(True, [first, second])

    def e_or(self, node: tuple) -> None:
        # l; NOT; JIF T; r; JIF F; T: CONST true; JUMP end; F: CONST false; end:
        # NOT enforces that l is BOOL; JIF then enforces it for r.
        self.expr(node[1])
        self.emit("NOT")
        to_true = self.emit("JUMP_IF_FALSE", 0)
        self.expr(node[2])
        to_false = self.emit("JUMP_IF_FALSE", 0)
        self.patch(to_true, self.here())
        self.emit("CONST", self.const(True))
        to_end = self.emit("JUMP", 0)
        self.patch(to_false, self.here())
        self.emit("CONST", self.const(False))
        self.patch(to_end, self.here())

    def finish_logic(self, _true_first: bool, false_jumps: list[int]) -> None:
        self.emit("CONST", self.const(True))
        to_end = self.emit("JUMP", 0)
        for at in false_jumps:
            self.patch(at, self.here())
        self.emit("CONST", self.const(False))
        self.patch(to_end, self.here())


def compile_source(src: str, *, optimize: bool = False) -> Program:
    tree = parse(src)
    if optimize:
        tree = fold_constants(tree)
    gen = _Generator()
    try:
        gen.stmt(tree)  # type: ignore[arg-type]
    except RecursionError:
        raise CompileError("program nesting too deep") from None
    gen.emit("HALT")
    return Program(gen.constants, gen.names, gen.code)

"""Binary codec for compiled programs."""

import struct
import zlib

from .compiler import Instr, Program
from .errors import SerializationError
from .opcodes import ARG_OPCODES, OPCODE_NUMBERS, OPCODES

MAGIC = b"MVM1"
VERSION = 1
NO_ARG = 0xFFFFFFFF
_INT_MIN = -(2 ** 63)
_INT_MAX = 2 ** 63 - 1


def _encode_constant(value: object) -> bytes:
    if type(value) is bool:
        return b"\x04" + struct.pack(">B", 1 if value else 0)
    if type(value) is int:
        if not _INT_MIN <= value <= _INT_MAX:
            raise SerializationError(f"INT constant {value} outside signed 64-bit range")
        return b"\x01" + struct.pack(">q", value)
    if type(value) is float:
        return b"\x02" + struct.pack(">d", value)
    if type(value) is str:
        try:
            raw = value.encode("utf-8")
        except UnicodeEncodeError as exc:
            raise SerializationError(f"string not encodable: {exc}") from None
        if len(raw) > 0xFFFFFFFF:
            raise SerializationError("string constant too long")
        return b"\x03" + struct.pack(">I", len(raw)) + raw
    raise SerializationError(f"unsupported constant type {type(value).__name__}")


def _encode_name(name: object) -> bytes:
    if type(name) is not str:
        raise SerializationError("variable names must be strings")
    try:
        raw = name.encode("utf-8")
    except UnicodeEncodeError as exc:
        raise SerializationError(f"name not encodable: {exc}") from None
    if len(raw) > 0xFFFF:
        raise SerializationError("variable name too long")
    return struct.pack(">H", len(raw)) + raw


def _encode_instr(instr: Instr) -> bytes:
    number = OPCODE_NUMBERS.get(instr.op)
    if number is None:
        raise SerializationError(f"unknown opcode {instr.op!r}")
    if instr.op in ARG_OPCODES:
        arg = instr.arg
        if type(arg) is not int or not 0 <= arg < NO_ARG:
            raise SerializationError(f"{instr.op} needs an argument in u32 range")
    else:
        if instr.arg is not None:
            raise SerializationError(f"{instr.op} takes no argument")
        arg = NO_ARG
    return struct.pack(">BI", number, arg)


def dumps(program: Program) -> bytes:
    if len(program.names) > 0xFFFF or len(program.constants) > 0xFFFF:
        raise SerializationError("too many names or constants")
    if len(program.instructions) > 0xFFFFFFFF:
        raise SerializationError("too many instructions")
    parts = [struct.pack(">BH", VERSION, len(program.names))]
    parts += [_encode_name(n) for n in program.names]
    parts.append(struct.pack(">H", len(program.constants)))
    parts += [_encode_constant(c) for c in program.constants]
    parts.append(struct.pack(">I", len(program.instructions)))
    parts += [_encode_instr(i) for i in program.instructions]
    body = b"".join(parts)
    return MAGIC + body + struct.pack(">I", zlib.crc32(body))


class _Reader:
    def __init__(self, data: bytes) -> None:
        self.data = data
        self.pos = 0

    def take(self, count: int) -> bytes:
        end = self.pos + count
        if end > len(self.data):
            raise SerializationError("truncated data")
        chunk = self.data[self.pos:end]
        self.pos = end
        return chunk

    def unpack(self, fmt: str) -> tuple:
        return struct.unpack(fmt, self.take(struct.calcsize(fmt)))

    def text(self, length: int) -> str:
        try:
            return self.take(length).decode("utf-8")
        except UnicodeDecodeError:
            raise SerializationError("invalid UTF-8") from None


def _decode_constant(reader: _Reader) -> object:
    (tag,) = reader.unpack(">B")
    if tag == 0x01:
        return reader.unpack(">q")[0]
    if tag == 0x02:
        return reader.unpack(">d")[0]
    if tag == 0x03:
        return reader.text(reader.unpack(">I")[0])
    if tag == 0x04:
        (flag,) = reader.unpack(">B")
        if flag not in (0, 1):
            raise SerializationError(f"invalid BOOL payload {flag}")
        return flag == 1
    raise SerializationError(f"unknown constant tag {tag:#04x}")


def _decode_instr(reader: _Reader) -> Instr:
    number, arg = reader.unpack(">BI")
    if not 1 <= number <= len(OPCODES):
        raise SerializationError(f"unknown opcode number {number}")
    op = OPCODES[number - 1]
    if op in ARG_OPCODES:
        if arg == NO_ARG:
            raise SerializationError(f"{op} is missing its argument")
        return Instr(op, arg)
    if arg != NO_ARG:
        raise SerializationError(f"{op} must not carry an argument")
    return Instr(op, None)


def loads(data: bytes) -> Program:
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise SerializationError("data must be bytes")
    data = bytes(data)
    if len(data) < len(MAGIC) or data[:len(MAGIC)] != MAGIC:
        raise SerializationError("bad magic")
    if len(data) < len(MAGIC) + 4:
        raise SerializationError("truncated data")
    body, (checksum,) = data[len(MAGIC):-4], struct.unpack(">I", data[-4:])
    if zlib.crc32(body) != checksum:
        raise SerializationError("checksum mismatch")
    reader = _Reader(body)
    if reader.unpack(">B")[0] != VERSION:
        raise SerializationError("unsupported version")
    names = [reader.text(reader.unpack(">H")[0]) for _ in range(reader.unpack(">H")[0])]
    constants = [_decode_constant(reader) for _ in range(reader.unpack(">H")[0])]
    instructions = [_decode_instr(reader) for _ in range(reader.unpack(">I")[0])]
    if reader.pos != len(body):
        raise SerializationError("trailing bytes")
    return Program(constants, names, instructions)

"""Human-readable listing of a program."""

from .compiler import Program


def _render_constant(value: object) -> str:
    if type(value) is bool:
        return "true" if value else "false"
    if type(value) is str:
        escaped = (
            value.replace("\\", "\\\\").replace('"', '\\"')
            .replace("\n", "\\n").replace("\t", "\\t")
        )
        return f'"{escaped}"'
    return str(value)


def disassemble(program: Program) -> str:
    lines = []
    for index, instr in enumerate(program.instructions):
        line = f"{index:04d} {instr.op}"
        if instr.arg is not None:
            line += f" {instr.arg}"
        pool = program.constants
        if instr.op == "CONST" and instr.arg is not None and 0 <= instr.arg < len(pool):
            line += f"  ; {_render_constant(pool[instr.arg])}"
        lines.append(line + "\n")
    return "".join(lines)

"""Command line interface."""

import argparse
import sys

from .compiler import compile_source
from .disassembler import disassemble
from .errors import MicroVMError
from .serializer import dumps, loads
from .vm import execute


class _UsageError(Exception):
    pass


def _positive_int(text: str) -> int:
    try:
        value = int(text)
    except ValueError:
        raise argparse.ArgumentTypeError(f"not a positive integer: {text!r}") from None
    if value <= 0:
        raise argparse.ArgumentTypeError(f"not a positive integer: {text!r}")
    return value


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="microvm")
    sub = parser.add_subparsers(dest="command", required=True)
    run = sub.add_parser("run", help="compile and execute a source file")
    run.add_argument("file")
    run.add_argument("--optimize", action="store_true")
    run.add_argument("--step-limit", type=_positive_int, default=100_000)
    build = sub.add_parser("build", help="compile a source file to a binary")
    build.add_argument("file")
    build.add_argument("out")
    build.add_argument("--optimize", action="store_true")
    run_bin = sub.add_parser("exec", help="execute a binary file")
    run_bin.add_argument("file")
    run_bin.add_argument("--step-limit", type=_positive_int, default=100_000)
    disasm = sub.add_parser("disasm", help="disassemble a binary file")
    disasm.add_argument("file")
    return parser


def _read_bytes(path: str) -> bytes:
    try:
        with open(path, "rb") as handle:
            return handle.read()
    except OSError as exc:
        raise _UsageError(f"cannot read {path}: {exc}") from None


def _read_source(path: str) -> str:
    try:
        return _read_bytes(path).decode("utf-8")
    except UnicodeDecodeError:
        raise _UsageError(f"cannot decode {path} as UTF-8") from None


def _dispatch(args: argparse.Namespace) -> str:
    """Run a command and return the text to print on success."""
    if args.command == "run":
        program = compile_source(_read_source(args.file), optimize=args.optimize)
        return "".join(line + "\n" for line in execute(program, step_limit=args.step_limit))
    if args.command == "build":
        data = dumps(compile_source(_read_source(args.file), optimize=args.optimize))
        try:
            with open(args.out, "wb") as handle:
                handle.write(data)
        except OSError as exc:
            raise _UsageError(f"cannot write {args.out}: {exc}") from None
        return ""
    program = loads(_read_bytes(args.file))
    if args.command == "exec":
        return "".join(line + "\n" for line in execute(program, step_limit=args.step_limit))
    return disassemble(program)


def main(argv: list[str] | None = None) -> int:
    try:
        args = _build_parser().parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    try:
        text = _dispatch(args)
    except _UsageError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    except MicroVMError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 3
    sys.stdout.write(text)
    sys.stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())
